export function dynamicResourceOptimizer(taskComplexity, availableResources) {
  const allocation = {};
  const baseAllocation = Math.floor(availableResources / taskComplexity);
  for (let i = 0; i < taskComplexity; i++) {
    allocation[`task_${i}`] = baseAllocation - (i * 0.1 * baseAllocation);
  }
  return allocation;
}